class BankError(Exception):
    """Общий предок всех банковских ошибок."""


class NotEnoughMoneyError(BankError):
    pass


class AccountBlockedError(BankError):
    pass


def pay(error_type):
    raise error_type('что-то пошло не так')


# Ловим конкретную ошибку:
try:
    pay(NotEnoughMoneyError)
except NotEnoughMoneyError:
    print('Недостаточно средств')

# А здесь — любую банковскую сразу:
try:
    pay(AccountBlockedError)
except BankError:
    print('Проблема со счётом')

class NotEnoughMoneyError(Exception):
    def __init__(self, balance, requested):
        self.balance = balance
        self.requested = requested
        self.shortage = requested - balance
        super().__init__(f'Не хватает {self.shortage} руб.')


try:
    raise NotEnoughMoneyError(500, 1200)
except NotEnoughMoneyError as error:
    print(error)             # Не хватает 700 руб.
    print(error.shortage)    # 700 — можно достать числом
    print(error.balance)     # 500
